fonts='<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=EB+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500;1,600&family=Hanken+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">'
common_css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#fff;font-family:"Hanken Grotesk",sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}button,input{font:inherit}a{color:inherit;text-decoration:none}button,a,input{-webkit-tap-highlight-color:transparent}button,a{touch-action:manipulation}button{cursor:pointer}svg{width:24px;height:24px;flex-shrink:0}a,button{transition:color .2s,background .2s,transform .2s,box-shadow .2s}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid #c7ef6b;outline-offset:5px}.brand{display:inline-flex;align-items:center;gap:10px;font-weight:600;letter-spacing:-.01em}.brand svg{width:26px;height:26px}h1,h2,p{margin:0}.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;border:0;font-weight:600}.primary{background:var(--paper);color:#121312}.ghost{color:#fff;border:1px solid rgba(255,255,255,.32);background:rgba(12,13,13,.72);backdrop-filter:blur(14px)}.socials{display:flex;align-items:center;justify-content:center}.socials svg{width:18px;height:18px}input{min-width:0;color:#fff}input::placeholder{color:rgba(255,255,255,.48)}.status{font-size:13px;color:var(--lime);min-height:18px;margin-top:10px}dialog{background:#111613;color:#fff;border:1px solid #ffffff30;border-radius:24px;padding:32px;width:min(640px,calc(100% - 32px));box-shadow:0 30px 120px #000a}dialog::backdrop{background:#000b;backdrop-filter:blur(8px)}dialog h2{font:400 36px "EB Garamond",serif;margin:8px 0 14px}dialog p{line-height:1.65;color:#ffffffb8}dialog .close{float:right;border:1px solid #ffffff30;background:#ffffff0c;color:#fff;border-radius:50%;width:34px;height:34px;font-size:23px}dialog video{width:100%;border-radius:12px;margin-top:20px}dialog .dialog-action{display:inline-flex;margin-top:24px;padding:13px 22px;border-radius:30px;background:var(--paper);color:var(--ink);font-weight:600}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}'''
common_js='''const modal=document.querySelector('dialog');const modalBody=modal.querySelector('.dialog-body');const copy={"Workflow builder":"Connect the steps, decisions, and people in your process with a visual workflow canvas.","AI automations":"Put repetitive work on autopilot. Add intelligent steps that classify requests and route work to the right team.","Smart forms":"Collect the information your team needs with forms that adapt to every response.","Data connections":"Bring your tools together, so information moves with your workflows.","Internal apps":"Build a workspace around the way your team works.","Mobile":"Your workflows, wherever work takes you. Highframe is designed for every screen.","Manifesto":"Your best ideas shouldn’t have to wait in a development queue. We believe every team should be able to build the tools it needs.","Press":"Highframe helps teams turn their processes into internal tools, without code.","Docs":"Start with a form, connect an action, and add a routing rule. Preview your workflow before publishing it.","Pricing":"Highframe is getting ready for launch. Join the waitlist for availability and pricing updates.","About":"We’re building Highframe to help teams create the tools they actually need.","Blog":"Stories about better workflows and building without code. Join the waitlist for updates.","Careers":"Help us build the next generation of internal tools. Opportunities will be shared at launch.","Customers":"Built for the teams doing the work — operations, people, finance, and beyond.","Privacy Policy":"This preview does not send your email to a server. Waitlist entries are saved only in this browser. External services, including Google Fonts, may receive standard connection information.","Terms of Use":"This is an interactive Highframe design preview. The workflow builder and account service are not connected in this preview.","Cookie Policy":"This preview does not set tracking cookies. It uses local storage only when you choose to join the preview waitlist."};
function openInfo(title){modalBody.innerHTML='';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=copy[title]||'See how Highframe can simplify the way your team works. Join the waitlist to hear when we launch.';const a=document.createElement('a');a.className='dialog-action';a.href='#waitlist';a.textContent='Join the waitlist';a.onclick=()=>{modal.close();setTimeout(()=>document.querySelector('input[type=email]').focus({preventScroll:true}),350)};modalBody.append(h,p,a);modal.showModal()}
document.querySelectorAll('[data-info]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openInfo(a.dataset.info)}));
document.querySelectorAll('[data-demo]').forEach(a=>a.addEventListener('click',()=>{modalBody.innerHTML='<h2>Meet your next workflow</h2><p>Build the tools your team actually needs.</p><video src="../assets/hero.mp4" controls autoplay muted playsinline></video>';modal.showModal()}));
modal.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('close',()=>{const video=modal.querySelector('video');if(video)video.pause()});modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const email=form.querySelector('input').value.trim();if(!form.reportValidity())return;try{localStorage.setItem('highframe-waitlist',email);form.parentElement.querySelector('.status').textContent="You’re on the preview list. Saved on this device."}catch{form.parentElement.querySelector('.status').textContent='Preview complete. Email service is not connected.'}form.querySelector('button').textContent='You’re on the list ✓'}));'''
