desktop_css=''' :root{--ink:#0c0d0d;--paper:#f4f3f0;--lime:#c7ef6b;--lime-deep:#b6e34f;--green:#16331f;--muted:rgba(255,255,255,.72);--line:rgba(255,255,255,.16);--dash-w:670px;--dash-x:59%;--dash-y:55px}body{background:#000}.wrap{width:calc(100% - 128px);max-width:1280px;margin:auto}.hero{min-height:880px;position:relative;isolation:isolate;overflow:visible}.hero-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;transform:scaleX(-1) scale(1.12);animation:kenburns 26s ease-in-out infinite alternate;z-index:-2;clip-path:inset(0)}@keyframes kenburns{to{transform:scaleX(-1) scale(1.2)}}.hero-clip{position:absolute;inset:0;overflow:hidden;z-index:-2}.hero-clip .hero-video{z-index:0}nav{height:88px;display:flex;align-items:center;justify-content:space-between;position:relative;z-index:5}nav .brand{font-size:20px}.nav-links{display:flex;align-items:center;gap:34px;font-size:15.5px;font-weight:500;color:#ffffffe0}.nav-links>a:hover{color:var(--lime)}.nav-links .book{padding:10px 20px;border:1px solid #ffffff66;border-radius:999px;background:#ffffff0a}.nav-group{position:relative}.nav-trigger{display:flex;align-items:center;gap:6px;border:0;background:none;color:inherit;padding:12px 0}.nav-trigger svg{width:17px;height:17px}.dropdown{display:none;position:absolute;left:-20px;top:44px;width:210px;padding:12px;background:#101713ed;backdrop-filter:blur(16px);border:1px solid var(--line);border-radius:16px;box-shadow:0 20px 50px #0005}.dropdown.open{display:grid}.dropdown a{padding:10px;border-radius:6px;font-size:14px}.dropdown a:hover{background:#ffffff0d;color:var(--lime)}.hero-grid{position:relative;display:grid;grid-template-columns:1fr}.hero-copy{padding:78px 0 110px;max-width:620px;position:relative;z-index:4}h1{font:400 62px/1.06 "EB Garamond",serif;letter-spacing:-.005em;text-wrap:balance;max-width:580px}.sub{font:400 22px/1.5 "EB Garamond",serif;color:var(--muted);max-width:430px;margin-top:24px}.cta{display:flex;gap:14px;margin-top:38px}.btn{height:54px;border-radius:999px;padding:0 25px;font-size:16px}.primary{box-shadow:0 8px 30px #0005}.primary:hover{transform:translateY(-2px);box-shadow:0 12px 38px #0008}.ghost:hover{background:#1e2921e6}.material-icons-round{font-size:23px}.dash{position:absolute;width:var(--dash-w);left:var(--dash-x);top:var(--dash-y);border-radius:16px;overflow:hidden;box-shadow:0 40px 90px -22px #000b,0 0 0 1px #ffffff0f;z-index:3;background:#f4f5f0}.dash iframe{border:0;display:block;width:100%;aspect-ratio:1456/1138}.hero{overflow-x:clip}.reveal{opacity:0;transform:translateY(22px);transition:opacity .8s cubic-bezier(.2,.7,.2,1),transform .8s cubic-bezier(.2,.7,.2,1);transition-delay:var(--delay,0s)}.dash.reveal{transform:translateX(46px) scale(.985)}.loaded .reveal{opacity:1;transform:none}.snap .reveal{transition:none!important}.footer{position:relative;isolation:isolate;margin-top:-120px;border-top:1px solid #ffffff24;border-radius:22px 22px 0 0}.footer::after{content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;backdrop-filter:blur(12px) saturate(120%);background:linear-gradient(#0a0c0b61,#0a0c0bcc);box-shadow:inset 0 1px 0 #ffffff2e}.footer-grid{display:grid;grid-template-columns:1.1fr 1fr 1fr 1.5fr;gap:30px;padding-top:72px;padding-bottom:64px}.link-col h3{font-size:13px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#ffffff73;margin:0 0 24px}.link-col a{display:block;font-size:16px;color:#ffffffd1;margin-bottom:14px;width:fit-content}.link-col a:hover{color:#fff;transform:translateX(2px)}.fbrand .brand{font-size:23px}.fbrand .brand svg{width:28px;height:28px}.fbrand p{font-size:17px;line-height:1.5;color:#ffffffb3;max-width:330px;margin:18px 0 24px}.waitlist{display:flex;align-items:center;gap:10px;background:#ffffff14;border:1px solid var(--line);border-radius:999px;padding:6px 6px 6px 20px;max-width:440px;backdrop-filter:blur(8px);box-shadow:inset 0 1px 0 #ffffff0a}.waitlist svg{width:17px;height:17px;color:#ffffff80}.waitlist input{width:100%;background:none;border:0;outline:none;font-size:15.5px}.waitlist button{border:0;background:#fff;color:var(--ink);border-radius:999px;padding:12px 20px;font-size:15px;font-weight:600;white-space:nowrap}.waitlist:focus-within{border-color:var(--lime)}.bottom{border-top:1px solid #ffffff1f;display:flex;align-items:center;justify-content:space-between;gap:22px;padding:26px 0 38px;font-size:14.5px;color:#ffffff8c}.socials{gap:22px;color:#fff9}.socials a:hover{color:#fff;transform:translateY(-2px)}.legal{display:flex;gap:28px;color:#fff9}.legal a:hover{color:#fff}.tweak-toggle{position:fixed;bottom:14px;left:14px;z-index:30;width:30px;height:30px;border:1px solid #ffffff25;border-radius:50%;background:#151b18;color:#ffffff90;font-size:17px}.tweak-panel{position:fixed;bottom:52px;left:14px;z-index:30;width:250px;background:#111b16f5;border:1px solid #ffffff30;border-radius:16px;padding:20px;box-shadow:0 12px 40px #0008;font-size:13px}.tweak-panel h3{margin:0 0 16px}.tweak-panel label{display:block;margin:12px 0}.tweak-panel input{width:100%;accent-color:var(--lime)}.tweak-panel button{padding:7px 14px;border:1px solid #ffffff30;border-radius:8px;background:transparent;color:#fff}@media(min-width:1500px){.wrap{max-width:1320px}}@media(max-width:1100px){h1{font-size:54px}.hero-copy{max-width:490px}.dash{--dash-x:54%;--dash-w:620px}.wrap{width:calc(100% - 80px)}.footer-grid{grid-template-columns:1fr 1fr 1fr 1.7fr;gap:20px}.waitlist{padding-left:14px;gap:6px}.waitlist button{padding:12px}.waitlist svg{display:none}.bottom{font-size:12px}.legal{gap:14px}}@media(max-width:860px){.nav-links{display:none}.wrap{width:calc(100% - 48px)}.hero{min-height:auto;padding-bottom:170px}.hero-copy{padding:44px 0 48px;max-width:620px}h1{font-size:42px}.dash{position:relative;left:auto;top:auto;width:100%;border-radius:14px}.footer-grid{grid-template-columns:1fr 1fr}.fbrand{grid-column:1/-1}.bottom{flex-direction:column;gap:24px}.fbrand p{max-width:440px}}'''
desktop=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Highframe — Build the tools your team actually needs</title><link rel="icon" href="data:,">{fonts}<link href="https://fonts.googleapis.com/icon?family=Material+Icons+Round" rel="stylesheet"><style>{common_css}{desktop_css}</style></head><body><section class="hero"><div class="hero-clip"><video class="hero-video" autoplay muted loop playsinline src="../assets/hero.mp4"></video></div><div class="wrap"><nav class="reveal"><a class="brand" href="#">{logo}Highframe</a><div class="nav-links">'''
for group in ['Product','Resources']:desktop+=f'<div class="nav-group"><button class="nav-trigger" aria-expanded="false">{group}{chev}</button><div class="dropdown">{links(groups[group])}</div></div>'
desktop+=f'''<a href="#" data-info="Pricing">Pricing</a><a href="#" data-info="Customers">Customers</a><a class="book" href="#" data-info="Book a demo">Book a demo</a></div></nav><div class="hero-grid"><div class="hero-copy"><h1 class="reveal" style="--delay:.12s">Build the tools your team <em>actually</em> needs</h1><p class="sub reveal" style="--delay:.26s">Turn any process into an intelligent form that routes data and triggers actions instantly.</p><div class="cta reveal" style="--delay:.4s"><a href="#waitlist" class="btn primary">Get started for free</a><button class="btn ghost" data-demo><span class="material-icons-round" aria-hidden="true">play_circle</span>Watch demo</button></div></div><div class="dash reveal" style="--delay:.5s"><iframe title="Highframe workflow builder preview" src="assets/dashboard-orchestrator.html"></iframe></div></div></div></section><footer class="footer"><div class="wrap"><div class="footer-grid">'''
for group in ['Product','Resources','Company']:desktop+=f'<div class="link-col"><h3>{group}</h3>{links(groups[group])}</div>'
desktop+=f'''<div class="fbrand"><a class="brand" href="#">{logo}Highframe</a><p>Skip the dev queue. Build internal workflows, smart forms, and automations without code.</p><div id="waitlist"><form class="waitlist">{mail}<input type="email" aria-label="Email address" placeholder="Your email address" autocomplete="email" required><button type="submit">Join waitlist</button></form><div class="status" role="status" aria-live="polite"></div></div></div></div><div class="bottom"><span>© 2026 Highframe. All rights reserved.</span><div class="socials">{social}</div><div class="legal">{links(groups['Legal'])}</div></div></div></footer>{dialog}<div id="tweaks"></div><script>{common_js}
const show=()=>{{document.body.classList.add('loaded')}};if(document.hidden){{document.body.classList.add('snap');show();document.addEventListener('visibilitychange',()=>{{if(!document.hidden){{document.body.classList.remove('loaded','snap');requestAnimationFrame(()=>requestAnimationFrame(show))}}}})}}else requestAnimationFrame(()=>requestAnimationFrame(show));
document.querySelectorAll('.nav-trigger').forEach(button=>button.onclick=()=>{{const open=button.getAttribute('aria-expanded')==='true';document.querySelectorAll('.nav-trigger').forEach(b=>{{b.setAttribute('aria-expanded','false');b.nextElementSibling.classList.remove('open')}});button.setAttribute('aria-expanded',String(!open));button.nextElementSibling.classList.toggle('open',!open)}});document.addEventListener('click',e=>{{if(!e.target.closest('.nav-group'))document.querySelectorAll('.nav-trigger').forEach(b=>{{b.setAttribute('aria-expanded','false');b.nextElementSibling.classList.remove('open')}})}});document.addEventListener('keydown',e=>{{if(e.key==='Escape')document.querySelectorAll('.nav-trigger').forEach(b=>{{b.setAttribute('aria-expanded','false');b.nextElementSibling.classList.remove('open')}})}});
</script><script src="../assets/react.production.min.js"></script><script src="../assets/react-dom.production.min.js"></script><script src="../assets/babel.min.js"></script><script type="text/babel">function Tweaks(){{const[open,setOpen]=React.useState(false);const[values,setValues]=React.useState([670,59,55]);function update(i,value){{const next=[...values];next[i]=+value;setValues(next);document.documentElement.style.setProperty(['--dash-w','--dash-x','--dash-y'][i],value+(i===1?'%':'px'))}}return <><button className="tweak-toggle" aria-label="Adjust dashboard position" aria-expanded={{open}} onClick={{()=>setOpen(!open)}}>⌘</button>{{open&&<div className="tweak-panel"><h3>Dashboard position</h3>{{['Width','Horizontal','Vertical'].map((label,i)=><label key={{label}}>{{label}} · {{values[i]}}{{i===1?'%':'px'}}<input aria-label={{label}} type="range" min={{[400,35,0][i]}} max={{[900,70,250][i]}} value={{values[i]}} onChange={{e=>update(i,e.target.value)}}/></label>)}}<button onClick={{()=>{{setValues([670,59,55]);[670,59,55].forEach((v,i)=>document.documentElement.style.setProperty(['--dash-w','--dash-x','--dash-y'][i],v+(i===1?'%':'px')))}}}}>Reset</button></div>}}</>}}ReactDOM.createRoot(document.getElementById('tweaks')).render(<Tweaks/>);</script></body></html>'''
