mobile_css=''' :root{--ink:#0c0d0d;--paper:#f4f3f0;--lime:#c7ef6b;--muted:rgba(255,255,255,.65);--line:rgba(255,255,255,.13);--card:rgba(255,255,255,.055)}body{background:#060707}.phone{max-width:430px;margin:auto;min-height:100dvh;background:#000;overflow:hidden}.hero{min-height:100dvh;display:flex;flex-direction:column;padding-bottom:28px;position:relative;isolation:isolate}.hero-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;transform:scaleX(-1);z-index:-2}.hero::after{content:"";position:absolute;width:280px;height:280px;left:50%;bottom:12%;transform:translateX(-50%);background:radial-gradient(circle,rgba(199,239,107,.18),transparent 70%);filter:blur(22px);z-index:-1;pointer-events:none}nav{display:flex;align-items:center;justify-content:space-between;padding:26px 22px 0;position:relative;z-index:10}.brand{font-size:18px}.brand svg{width:24px;height:24px}.menu-toggle{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;width:42px;height:42px;border-radius:11px;border:1px solid #ffffff38;background:#00000047;backdrop-filter:blur(12px)}.menu-toggle span{width:18px;height:1.4px;background:#fff;transition:transform .25s,opacity .25s}.menu-toggle[aria-expanded=true] span:first-child{transform:translateY(6.4px) rotate(45deg)}.menu-toggle[aria-expanded=true] span:nth-child(2){opacity:0}.menu-toggle[aria-expanded=true] span:last-child{transform:translateY(-6.4px) rotate(-45deg)}.menu{position:absolute;top:78px;left:22px;right:22px;padding:18px;border:1px solid #ffffff30;background:#101713f5;backdrop-filter:blur(18px);border-radius:18px;box-shadow:0 20px 70px #0007;display:none}.menu.open{display:grid;gap:4px}.menu a{padding:12px;border-radius:8px;font-size:16px}.menu a:last-child{background:var(--paper);color:var(--ink);text-align:center;margin-top:8px}.hero-body{display:flex;flex-direction:column;align-items:center;text-align:center;padding:32px 22px 38px;z-index:5}.badge{display:none}.badge i{width:7px;height:7px;background:var(--lime);box-shadow:0 0 10px var(--lime)}h1{font:400 clamp(44px,12vw,58px)/1 "EB Garamond",serif;letter-spacing:-.025em;max-width:9ch;text-shadow:0 10px 30px #0005}h1 em{font-style:italic;color:var(--lime)}.sub{font-size:16px;line-height:1.62;color:#ffffffc2;max-width:31ch;margin-top:22px}.cta{display:flex;flex-direction:column;gap:11px;width:100%;max-width:340px;margin-top:28px}.btn{height:58px;border-radius:18px;font-size:15.5px}.btn:active{transform:scale(.975);opacity:.9}.ghost{background:rgba(12,13,13,.78);border-color:#ffffff4d}.hero-preview{position:relative;width:min(88vw,368px);margin:0 auto 8px;border-radius:32px;padding:10px;transform:perspective(1400px) rotateX(17deg) rotateY(-8deg) rotateZ(1deg) translateY(10px);background:linear-gradient(125deg,#ffffff80,#ffffff12 26%,#a4d67136 70%,#ffffff70);box-shadow:0 30px 60px -15px #000b,inset 0 1px 2px #ffffff90,0 0 40px #9bcb5715;animation:float 6.5s ease-in-out infinite;z-index:2}.hero-preview::before{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(130deg,#fff4,transparent 30%,transparent 75%,#fff2);pointer-events:none}.hero-preview::after{content:"";position:absolute;inset:70% 15% -18%;background:#9bd86235;filter:blur(35px);z-index:-1;border-radius:50%}.preview-shell{position:relative;overflow:hidden;border-radius:23px;background:#f4f5f0;border:1px solid #ffffff70;box-shadow:inset 0 0 16px #ffffff30;backdrop-filter:blur(14px)}.preview-shell::before{content:"";position:absolute;inset:0;border:1px solid transparent;border-radius:inherit;background:linear-gradient(135deg,#fff9,transparent,#fff3) border-box;mask:linear-gradient(#fff 0 0) padding-box,linear-gradient(#fff 0 0);mask-composite:exclude;pointer-events:none}.preview-shell iframe{display:block;width:100%;aspect-ratio:1456/1138;border:0}@keyframes float{50%{transform:perspective(1400px) rotateX(14deg) rotateY(-5deg) rotateZ(-1deg) translateY(0)}}.r{opacity:0;transform:translateY(20px);transition:opacity .75s cubic-bezier(.16,1,.3,1),transform .75s cubic-bezier(.16,1,.3,1);transition-delay:var(--delay,0s)}.r.in{opacity:1;transform:none}.hero-preview.r.in{transform:perspective(1400px) rotateX(17deg) rotateY(-8deg) rotateZ(1deg) translateY(10px)}.foot{position:relative;background:#000;border-top:1px solid var(--line);border-radius:26px 26px 0 0;padding:54px 22px 44px;box-shadow:0 1px 0 #ffffff1a inset,0 -1px 0 #00000047 inset}.foot::after{content:"";position:absolute;top:0;left:20px;right:20px;height:1px;background:linear-gradient(90deg,transparent,#ffffff80,transparent)}.mail-circle{display:flex;align-items:center;justify-content:center;width:58px;height:58px;margin:0 auto 23px;border-radius:50%;background:#ffffff21;border:1px solid #ffffff4d;box-shadow:0 0 28px #ffffff0e,inset 0 1px 0 #ffffff30;backdrop-filter:blur(12px)}.mail-circle svg{width:26px;height:26px}.foot h2{font:400 38px/1.08 "EB Garamond",serif;letter-spacing:-.015em;text-align:center}.foot-sub{font-size:15px;line-height:1.55;color:rgba(210,195,210,.72);text-align:center;max-width:300px;margin:16px auto 26px}.waitlist{display:flex;flex-direction:column;gap:10px}.waitlist input{height:52px;padding:0 16px;background:#ffffff0f;border:1px solid #fff3;border-radius:14px;font-size:15px;backdrop-filter:blur(10px);transition:border .2s,box-shadow .2s}.waitlist input:focus{outline:0;border-color:#ffffff80;box-shadow:0 0 0 3px #ffffff0d}.waitlist button{height:52px;border:0;border-radius:14px;background:var(--paper);color:var(--ink);font-size:15.5px;font-weight:600;box-shadow:0 10px 36px -14px #ffffff61;display:flex;align-items:center;justify-content:center;gap:12px}.waitlist button svg{width:20px;height:20px}.status{text-align:center}.accordion{margin-top:26px}.accordion-section{border-bottom:1px solid var(--line)}.accordion-trigger{width:100%;display:flex;align-items:center;justify-content:space-between;padding:21px 0;border:0;background:transparent;font-size:16px;font-weight:500;color:rgba(235,220,230,.86);text-align:left}.accordion-trigger svg{width:19px;height:19px;transition:transform .26s cubic-bezier(.4,0,.2,1)}.accordion-trigger[aria-expanded=true] svg{transform:rotate(180deg)}.accordion-body{max-height:0;overflow:hidden;visibility:hidden;transition:max-height .3s,visibility .3s}.accordion-body.open{max-height:300px;visibility:visible}.accordion-body a{display:block;color:#fff9;font-size:15px;padding:8px 0}.accordion-body a:last-child{padding-bottom:22px}.socials{gap:10px;margin:32px 0 26px}.socials a{width:46px;height:46px;display:grid;place-items:center;border:1px solid #ffffff2e;background:#ffffff0a;border-radius:50%;color:rgba(215,190,210,.72);backdrop-filter:blur(8px)}.socials a:hover{color:#fff;background:#ffffff15;border-color:#fff6;box-shadow:0 0 24px #ffffff10}.brand-card{padding:24px 12px;text-align:center;background:#ffffff12;border:1px solid #ffffff29;border-radius:18px;backdrop-filter:blur(14px)}.brand-card .brand{font-size:20px}.brand-card .brand svg{width:22px;height:22px}.brand-card p{font-size:13px;color:#ffffff61;margin-top:12px}@media(max-height:760px){.hero-body{justify-content:flex-end;padding-top:26px;padding-bottom:25px}h1{font-size:clamp(42px,11.5vw,50px)}.sub{margin-top:17px}.cta{margin-top:22px}}'''
mobile=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Highframe — Built for your team</title><link rel="icon" href="data:,">{fonts}<style>{common_css}{mobile_css}</style></head><body><main class="phone"><section class="hero"><video class="hero-video" autoplay muted playsinline src="../assets/hero.mp4"></video><nav class="r"><a class="brand" href="#">{logo}Highframe</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span><span></span></button><div class="menu" id="mobile-menu"><a href="#" data-info="Workflow builder">Product</a><a href="#" data-info="Docs">Resources</a><a href="#" data-info="Pricing">Pricing</a><a href="#" data-info="Customers">Customers</a><a href="#" data-info="Book a demo">Book a demo</a></div></nav><div class="hero-body"><div class="badge"><i></i>AI-Powered Workflow</div><h1 class="r" style="--delay:.1s">Build the tools your team <em>actually</em> needs</h1><p class="sub r" style="--delay:.22s">Turn any process into an intelligent form that routes data and triggers actions instantly.</p><div class="cta r" style="--delay:.34s"><a class="btn primary" href="#waitlist">Start Free Trial</a><button class="btn ghost" data-demo>{play}Watch Demo</button></div></div><div class="hero-preview r" style="--delay:.46s"><div class="preview-shell"><iframe title="Highframe workflow builder preview" src="dashboard-orchestrator.html"></iframe></div></div></section><footer class="foot"><div class="mail-circle r">{mail}</div><h2 class="r" style="--delay:.07s">Skip the dev queue</h2><p class="foot-sub r" style="--delay:.13s">Build internal workflows, smart forms, and automations without code.</p><div id="waitlist" class="r" style="--delay:.19s"><form class="waitlist"><input type="email" aria-label="Email address" placeholder="Your email address" autocomplete="email" required><button type="submit">Sign up for waitlist {arrow}</button></form><div class="status" role="status" aria-live="polite"></div></div><div class="accordion r" style="--delay:.25s">'''
for i,(group,items) in enumerate(groups.items()):mobile+=f'<section class="accordion-section"><button class="accordion-trigger" aria-expanded="false" aria-controls="section-{i}">{group}{chev}</button><div class="accordion-body" id="section-{i}">{links(items)}</div></section>'
mobile+=f'''</div><div class="socials r" style="--delay:.37s">{social}</div><div class="brand-card r" style="--delay:.43s"><a href="#" class="brand">{logo}Highframe</a><p>© 2026 Highframe. All rights reserved.</p></div></footer></main>{dialog}<script>{common_js}
const heroVideo=document.querySelector('.hero-video');heroVideo.addEventListener('timeupdate',()=>{{if(heroVideo.currentTime>=2){{heroVideo.currentTime=0;heroVideo.play().catch(()=>{{}})}}}});heroVideo.addEventListener('ended',()=>{{heroVideo.currentTime=0;heroVideo.play().catch(()=>{{}})}});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{{if(entry.isIntersecting){{entry.target.classList.add('in');observer.unobserve(entry.target)}}}}),{{threshold:.08}});document.querySelectorAll('.hero .r').forEach(el=>requestAnimationFrame(()=>el.classList.add('in')));document.querySelectorAll('.foot .r').forEach(el=>observer.observe(el));
const menuButton=document.querySelector('.menu-toggle');const menu=document.querySelector('.menu');menuButton.onclick=()=>{{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.classList.toggle('open',open)}};menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{{menuButton.setAttribute('aria-expanded','false');menu.classList.remove('open')}}));document.addEventListener('keydown',e=>{{if(e.key==='Escape'){{menuButton.setAttribute('aria-expanded','false');menu.classList.remove('open')}}}});
document.querySelectorAll('.accordion-trigger').forEach(button=>button.onclick=()=>{{const open=button.getAttribute('aria-expanded')==='true';document.querySelectorAll('.accordion-trigger').forEach(other=>{{other.setAttribute('aria-expanded','false');other.nextElementSibling.classList.remove('open')}});button.setAttribute('aria-expanded',String(!open));button.nextElementSibling.classList.toggle('open',!open)}});
</script></body></html>'''
(root/'mobile/index.html').write_text(mobile)
